// NFR-002 model size (TASK-010, spec T6): "a single IFC of >= 100 MB and a multi-model set of >= 100 MB total load in
// the builder without worker or tab crash, with progress for conversion and extraction, in <= 60 s per 100 MB IFC
// (median of 3, environment and peak memory recorded)". Verify by: the synthetic >= 100 MB fixture and the
// multi-model set (Testing -> Test data).
//   single file   synthetic-castle-x3.ifc (151.8 MB, generated by scripts/fetch-fixtures.mjs from SampleCastle)
//   multi-model   SampleCastle twice + Revit MEP (127.7 MB, three files in one batch; the R-2 smoke set of TASK-002)
// Each of the 3 runs opens a fresh builder page (same context: the CDN cache routes of the network guard) and loads
// the set through the file input. Per run, recorded and asserted:
//   seconds       file input -> load batch finished (phase ready), Node clock     -> median <= 60 s per 100 MB asserted
//   progress      overlay texts `<file> – Konvertierung: n %` and `<file> – Extraktion: n %` seen      -> asserted
//   crash         page `crash` event, worker `error` (too-large), load errors                          -> none asserted
//   memory        peak page JS heap (CDP) and peak RSS of all Chromium processes (/proc)               -> recorded
//   maxSilenceMs  longest gap between two conversion-worker messages (the stall timeout must exceed it) -> recorded
// Runs in the `file` project only (the user's path), never at the same time as another perf spec (perf-lock).
import { statSync } from "node:fs";
import { test, expect } from "../support/perf-lock.mjs";
import { fetched, openBuilder } from "../support/builder.mjs";
import { perfEnvironment, sampleMemory } from "../support/perf-memory.mjs";

const SECONDS_PER_100MB = 60; // NFR-002
const RUNS = 3;
const median = (xs) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)];

const SETS = {
  "single synthetic IFC": [fetched("synthetic-castle-x3.ifc")],
  "multi-model set": ["Ifc2x3_SampleCastle.ifc", "Ifc2x3_SampleCastle.ifc", "Ifc4_Revit_MEP.ifc"].map(fetched),
};

/** One load of files into a fresh builder page; returns the run's measurements. */
async function loadRun(context, files) {
  const page = await context.newPage();
  let crashed = false;
  page.on("crash", () => (crashed = true));
  try {
    const errors = await openBuilder(page);
    const environment = await perfEnvironment(page);
    await page.evaluate(() => {
      window.__seen = [];
      window.__silence = [];
      new MutationObserver(() => {
        const text = document.getElementById("cv-overlay-text").textContent;
        if (text && window.__seen[window.__seen.length - 1] !== text) window.__seen.push(text);
        const c = window.__calc.conversion;
        if (c && !window.__silence.some((s) => s.fileName === c.fileName && s.ms === c.ms)) window.__silence.push(c);
      }).observe(document.getElementById("cv-overlay"), { subtree: true, childList: true, characterData: true });
    });
    const memory = await sampleMemory(page);
    const before = await page.evaluate(() => window.__calc.loads);
    const t0 = Date.now();
    await page.locator("#cv-file-input").setInputFiles(files);
    await page.waitForFunction((n) => window.__calc.loads > n && window.__calc.phase === "ready", before, {
      timeout: 840_000,
      polling: 500,
    });
    const seconds = (Date.now() - t0) / 1000;
    const peaks = await memory.stop();
    const hook = await page.evaluate(() => ({
      models: window.__calc.models.map((m) => ({
        modell: m.modell,
        elements: m.elements,
        withGeometry: m.withGeometry,
      })),
      rows: window.__calc.rows.length,
      catalog: window.__calc.catalog.length,
      loadErrors: window.__calc.loadErrors,
      modelCount: window.__calc.modelCount,
      seen: window.__seen,
      conversions: window.__silence.concat(window.__calc.conversion ? [window.__calc.conversion] : []),
    }));
    return { seconds, crashed, errors, environment, ...peaks, ...hook };
  } finally {
    await page.close();
  }
}

for (const [name, files] of Object.entries(SETS)) {
  test(`@perf @NFR-002 @REQ-001 ${name} (>= 100 MB) loads without crash, with progress, within 60 s per 100 MB (median of 3)`, async ({
    context,
  }, info) => {
    test.skip(info.project.name !== "file", "one run is enough; the file project is the user's path");
    test.setTimeout(3_000_000);
    const bytes = files.reduce((n, f) => n + statSync(f).size, 0);
    expect(bytes).toBeGreaterThanOrEqual(100e6);
    const mb = bytes / 1e6;
    const runs = [];
    for (let i = 0; i < RUNS; i++) runs.push(await loadRun(context, files));

    for (const r of runs) {
      expect(r.crashed, "no tab crash").toBe(false);
      expect(r.loadErrors, "no worker crash or load error").toEqual([]);
      expect(r.modelCount).toBe(files.length);
      expect(r.errors).toEqual([]);
      for (const f of files.map((p) => p.split("/").pop())) {
        expect(
          r.seen.some((t) => t.startsWith(`${f} – Konvertierung: `) && /\d+ %$/.test(t)),
          `${f}: conversion progress`,
        ).toBe(true);
        expect(
          r.seen.some((t) => t.startsWith(`${f} – Extraktion: `) && /\d+ %$/.test(t)),
          `${f}: extraction progress`,
        ).toBe(true);
      }
    }
    // equal results in every run
    for (const r of runs.slice(1)) expect(r.models).toEqual(runs[0].models);

    const secondsMedian = median(runs.map((r) => r.seconds));
    const per100 = (secondsMedian / mb) * 100;
    const silences = runs.flatMap((r) => r.conversions.map((c) => c.maxSilenceMs));
    const report = {
      set: name,
      files: files.map((f) => f.split("/").pop()),
      MB: Math.round(mb * 10) / 10,
      rows: runs[0].rows,
      catalogEntries: runs[0].catalog,
      models: runs[0].models,
      seconds: runs.map((r) => Math.round(r.seconds * 10) / 10),
      secondsMedian: Math.round(secondsMedian * 10) / 10,
      secondsPer100MB: Math.round(per100 * 10) / 10,
      peakPageHeapMB: runs.map((r) => r.pageHeapMB),
      peakChromiumRssMB: runs.map((r) => r.rssMB),
      conversionMaxSilenceMs: Math.max(...silences),
      environment: runs.map((r) => r.environment),
    };
    console.log(`[perf NFR-002] ${JSON.stringify(report)}`);
    info.annotations.push({ type: "nfr-002", description: JSON.stringify(report) });
    expect(per100, "NFR-002: <= 60 s per 100 MB IFC (median of 3)").toBeLessThanOrEqual(SECONDS_PER_100MB);
  });
}
